import {Engine} from './engine.js';
import {makeWorld} from './worlds.js';
import {Caretaker} from './caretaker.js';
import {saveWorld,loadWorld} from './storage.js';
const $=id=>document.getElementById(id),N=128;
const defaults={dt:.1,speed:1,radius:13,massConserve:false,genome:true,metabolism:true,eat:true,predPayoff:.35,mu:.15,sigma:.017,mut:.003,light:.35,time:0,curiosity:0,massScale:1,poke:[-1,-1],pokeR:.045,pokeAmt:.9,pokeErase:false};
const params={...defaults,poke:[-1,-1]};
let depleted=false,renderFailure=false;
let engine,running=!matchMedia('(prefers-reduced-motion: reduce)').matches,tick=0,seed=260924,preset='glider',caretaker=new Caretaker(),entries=[],baseline=1,lastSample=null,saveBusy=false,checkpoint=null,lastDecision=0,lastJournal=0;
const buf=new Float32Array(N*N*4),aux=new Float32Array(N*N*4),previous=new Float32Array(N*N);
let hasPrevious=false;
let center={x:-.15,y:0};
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),3500);}
function journal(text){entries.unshift({tick,text});entries=entries.slice(0,80);renderJournal();}
function renderJournal(){$('journal').replaceChildren(...entries.slice(0,8).map(e=>{const li=document.createElement('li'),time=document.createElement('time');time.textContent=`STEP ${e.tick.toLocaleString()}`;li.append(time,document.createTextNode(e.text));return li;}));$('moments').textContent=entries.length;}
function syncControls(){$('light').value=params.light;$('light-value').textContent=`${Math.round(params.light*100)}%`;$('mutation').value=params.mut;$('mutation-value').textContent=params.mut.toFixed(3);$('speed').value=params.speed;$('world').value=preset;}
function reportFailure(message){renderFailure=true;running=false;$('play').textContent='Resume';$('status').textContent='RENDERING STOPPED';$('error').hidden=false;$('error').replaceChildren(document.createTextNode(message+' Your saved checkpoint is kept. '));const reload=document.createElement('button');reload.textContent='Reload renderer';reload.onclick=()=>location.reload();$('error').append(reload);document.querySelectorAll('.controls button,.controls select,aside input,aside select,#save,#restore,#snapshot,#export,#import').forEach(el=>el.disabled=true);}
function showHealth(m){depleted=m.peak<.04;$('world-health').hidden=!depleted;if(depleted){running=false;$('play').textContent='Resume';$('health-text').textContent='Tissue has faded below the visible threshold (peak cell mass < 0.04). The simulation is paused, not a loading screen. Adding energy does not reseed tissue. Restart with defaults, or restore a saved world.';} }
function sample(){engine.readback(buf);engine.readback(aux,'s1');for(let i=0;i<buf.length;i++)if(!Number.isFinite(buf[i])||!Number.isFinite(aux[i]))throw new Error('The simulation produced invalid numeric values.');let peak=0,mass=0,energy=0,activity=0,cx=0,sx=0,cy=0,sy=0;for(let i=0;i<N*N;i++){const w=buf[i*4];peak=Math.max(peak,w);cx+=w*Math.cos((i%N)/N*2*Math.PI);sx+=w*Math.sin((i%N)/N*2*Math.PI);cy+=w*Math.cos(Math.floor(i/N)/N*2*Math.PI);sy+=w*Math.sin(Math.floor(i/N)/N*2*Math.PI);mass+=w;energy+=buf[i*4+1];if(hasPrevious)activity+=Math.abs(buf[i*4]-previous[i]);previous[i]=buf[i*4];}if(mass>1)center={x:((Math.atan2(sx,cx)/(2*Math.PI)+1)%1)-.5,y:((Math.atan2(sy,cy)/(2*Math.PI)+1)%1)-.5};hasPrevious=true;lastSample={mass,peak,energy,activity,ratio:mass/baseline,energyPerMass:energy/Math.max(mass,1)};$('mass').textContent=mass.toFixed(1);$('energy').textContent=energy.toFixed(1);$('activity').textContent=(Math.min(1,activity/(2*Math.max(mass,1)))*100).toFixed(1)+'%';return lastSample;}
function initialize(){depleted=false;$('world-health').hidden=true;engine.seed(makeWorld(preset,N,N,{radius:13,seed}));tick=0;params.time=0;lastDecision=0;lastJournal=0;hasPrevious=false;caretaker=new Caretaker();entries=[];baseline=sample().mass;baseline=Math.max(1,baseline);journal(`A new ${$('world').selectedOptions[0].text.toLowerCase()} world begins.`);$('seed-label').textContent=`SEED ${seed}`;$('lessons').textContent='0';$('reward').textContent='0.00';$('learning').textContent='Learning from mass-change feedback.';$('decision').textContent='Observing the first moments';}
function resize(){const r=$('viewport').getBoundingClientRect();const d=Math.min(devicePixelRatio||1,2);$('sim').width=Math.round(r.width*d);$('sim').height=Math.round(r.height*d);}
function step(){params.time+=params.dt;engine.step(params);tick++;if(tick%30===0){const m=sample();showHealth(m);if(!depleted&&$('auto').checked&&tick-lastDecision>=180){const a=caretaker.observe(m);params.light=a.light;params.mut=a.mut;lastDecision=tick;syncControls();$('decision').textContent=a.label;$('lessons').textContent=caretaker.updates;$('reward').textContent=caretaker.reward.toFixed(2);$('learning').textContent=caretaker.updates?'Updated from the previous intervention.':'Trying its first environmental change.';journal(a.label+'.');}if(tick-lastJournal>=900){journal(m.mass>1?`Mass ${m.mass.toFixed(1)} · stored energy ${m.energy.toFixed(1)}.`:'Living mass has fallen below 1. The world may have collapsed.');lastJournal=tick;}}}
function draw(){const aspect=$('sim').width/$('sim').height;engine.render(+$('view').value,{x:$('camera').value==='follow'&&preset==='glider'?center.x:0,y:$('camera').value==='follow'&&preset==='glider'?center.y:0,zoom:$('camera').value==='follow'&&preset==='glider'?2:1},{showLight:false,lightGrad:false,aspect});$('ticks').textContent=tick.toLocaleString();$('status').textContent=depleted?'LOW TISSUE / PAUSED':running?'LIVE / LOCAL':'PAUSED';}
let lastFrame=0;
function loop(now){if(now-lastFrame>=1000/30){lastFrame=now;if(!renderFailure){try{if(running&&!document.hidden)for(let k=0;k<params.speed&&running;k++)step();draw();}catch(e){reportFailure(e.message);}}}requestAnimationFrame(loop);}
function snapshotState(){engine.readback(buf);engine.readback(aux,'s1');return {version:1,size:N,s0:buf.slice(),s1:aux.slice(),params:{...params},tick,seed,preset,baseline,entries:entries.slice(),caretaker:caretaker.serialize(),auto:$('auto').checked,savedAt:new Date().toISOString()};}
async function save(){if(saveBusy)return;saveBusy=true;try{journal('Memory checkpoint saved.');checkpoint=snapshotState();await saveWorld(checkpoint);$('restore').disabled=false;$('saved').textContent=`Saved on this device · ${new Date(checkpoint.savedAt).toLocaleTimeString()}`;toast('World state + caretaker learning saved.');}catch(e){entries=entries.filter(x=>x.text!=='Memory checkpoint saved.');renderJournal();toast('Save failed. Try Export world to keep a copy.');}finally{saveBusy=false;}}
function restore(){if(!checkpoint||renderFailure)return;depleted=false;$('world-health').hidden=true;engine.seed(checkpoint);Object.assign(params,checkpoint.params);tick=checkpoint.tick;seed=checkpoint.seed;preset=checkpoint.preset;baseline=checkpoint.baseline;entries=checkpoint.entries.slice();caretaker=new Caretaker(checkpoint.caretaker);$('auto').checked=checkpoint.auto;lastDecision=tick;lastJournal=tick;hasPrevious=false;syncControls();showHealth(sample());journal('Returned to a saved world.');$('lessons').textContent=caretaker.updates;$('reward').textContent='0.00';$('decision').textContent='Resumed saved learning';$('seed-label').textContent=`SEED ${seed}`;toast('Memory restored.');}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function copyPost(){const text='Meet ECHO. A tiny artificial-life world with a learning caretaker.\n\nWatch it move. Change its environment. Save its history. Come back.\n\nBuilt on the open-source Genesis Engine. Browser experiment, not a claim of consciousness.\n\nLife leaves a trace.';try{await navigator.clipboard.writeText(text);toast('Post copied. Add your demo link before posting.');}catch{download(new Blob([text],{type:'text/plain'}),'echo-post.txt');}}
async function boot(){try{engine=new Engine($('sim'),N,N);if(!engine.ok())throw new Error('This experiment needs WebGL2 and floating-point textures. Try a recent Chrome, Edge, Firefox or Safari with hardware acceleration enabled.');resize();initialize();$('play').textContent=running?'Pause':'Resume';$('restart').onclick=()=>{Object.assign(params,defaults,{poke:[-1,-1]});$('view').value='0';$('camera').value='fixed';$('auto').checked=true;running=!matchMedia('(prefers-reduced-motion: reduce)').matches;initialize();syncControls();$('play').textContent=running?'Pause':'Resume';draw();toast('Same seed restarted with default settings. Saved checkpoint kept.');};$('health-restart').onclick=()=>$('restart').click();$('view').onchange=draw;$('camera').onchange=draw;window.addEventListener('resize',resize);$('play').onclick=()=>{running=!running;$('play').textContent=running?'Pause':'Resume';};$('step').onclick=()=>{running=false;$('play').textContent='Resume';step();sample();draw();};$('speed').onchange=()=>params.speed=+$('speed').value;$('world').onchange=()=>{depleted=false;$('world-health').hidden=true;preset=$('world').value;seed=(seed+7919)%1000000;initialize();draw();};for(const [id,key] of [['light','light'],['mutation','mut']]){$(id).oninput=()=>{params[key]=+$(id).value;$('auto').checked=false;caretaker.last=null;syncControls();$('decision').textContent='You are tending the environment';};$(id).onchange=()=>journal(`${key==='light'?'Light supply':'Mutation rate'} changed to ${params[key]}.`);}$('auto').onchange=()=>{caretaker.last=null;lastDecision=tick;journal($('auto').checked?'Learning caretaker activated.':'Learning caretaker paused.');$('decision').textContent=$('auto').checked?'Observing before the next decision':'You are tending the environment';};$('feed').onclick=()=>{engine.readback(aux,'s1');engine.readback(buf);for(let i=0;i<N*N;i++)aux[i*4+1]+=0.025;engine.seed({s0:buf,s1:aux});journal('You added 409.6 units to the free-energy pool.');sample();toast('Energy added to the environment.');};$('save').onclick=save;$('restore').onclick=restore;$('export').onclick=()=>{const s=snapshotState();s.s0=Array.from(s.s0);s.s1=Array.from(s.s1);download(new Blob([JSON.stringify(s)],{type:'application/json'}),`echo-world-${tick}.json`);};$('snapshot').onclick=()=>{draw();const c=document.createElement('canvas');c.width=1200;c.height=675;const ctx=c.getContext('2d');ctx.fillStyle='#0c1110';ctx.fillRect(0,0,1200,675);const sim=$('sim');ctx.drawImage(sim,300,0,900,675);ctx.fillStyle='#c8fb75';ctx.font='22px monospace';ctx.fillText('◎ ECHO',45,60);ctx.font='44px Georgia';ctx.fillText('Life leaves',45,290);ctx.fillText('a trace.',45,343);ctx.fillStyle='#e5eadc';ctx.font='15px monospace';ctx.fillText(`STEP ${tick} / SEED ${seed}`,45,575);ctx.font='13px monospace';ctx.fillText('Artificial-life experiment',45,605);ctx.fillText('Built on Genesis Engine · MIT',45,630);c.toBlob(b=>b?download(b,`echo-${tick}.png`):toast('Frame export failed.'));};$('tweet').onclick=copyPost;
$('import').onclick=()=>$('import-file').click();
$('import-file').onchange=async()=>{try{const file=$('import-file').files[0];if(!file)return;if(file.size>12_000_000)throw new Error('File is too large.');const s=JSON.parse(await file.text());
if(s.version!==1||s.size!==N||!['glider','garden','collide','soup'].includes(s.preset)||!Number.isInteger(s.tick)||s.tick<0||!Number.isFinite(s.baseline)||s.baseline<=0||!Number.isInteger(s.seed)||typeof s.auto!=='boolean')throw new Error('Unsupported world file.');
for(const k of ['s0','s1'])if(!Array.isArray(s[k])||s[k].length!==N*N*4||!s[k].every(v=>Number.isFinite(v)&&Math.abs(v)<=1e6))throw new Error('Invalid world state.');
const ranges={dt:[.01,.2],speed:[1,6],radius:[13,13],predPayoff:[0,1],mu:[.05,.4],sigma:[.001,.1],mut:[0,.015],light:[0,1],time:[0,1e12],curiosity:[0,1],massScale:[.9,1.1],pokeR:[0,.1],pokeAmt:[0,1]};
for(const [k,[lo,hi]] of Object.entries(ranges))if(!Number.isFinite(s.params?.[k])||s.params[k]<lo||s.params[k]>hi)throw new Error('Invalid environment settings.');
if(![1,3,6].includes(s.params.speed))throw new Error('Invalid speed.');
for(const k of ['massConserve','genome','metabolism','eat','pokeErase'])if(typeof s.params[k]!=='boolean')throw new Error('Invalid environment toggle.');
if(!Array.isArray(s.entries)||s.entries.length>80||s.entries.some(e=>!Number.isInteger(e.tick)||typeof e.text!=='string'||e.text.length>300))throw new Error('Invalid journal.');
if(!s.caretaker||!Number.isInteger(s.caretaker.updates)||s.caretaker.updates<0||!s.caretaker.q||Array.isArray(s.caretaker.q)||typeof s.caretaker.q!=='object'||Object.entries(s.caretaker.q).some(([k,v])=>! /^[0-2]:[0-2]$/.test(k)||!Array.isArray(v)||v.length!==4||v.some(x=>!Number.isFinite(x)||Math.abs(x)>100)))throw new Error('Invalid caretaker memory.');
s.s0=Float32Array.from(s.s0);s.s1=Float32Array.from(s.s1);s.params.poke=[-1,-1];checkpoint=s;restore();$('saved').textContent='Imported world · press Save memory to keep it here.';$('restore').disabled=false;toast('World imported. Save memory to store it on this device.');
}catch(e){toast('Import failed: '+e.message);}finally{$('import-file').value='';}};try{const loaded=await loadWorld();if(!checkpoint)checkpoint=loaded;if(checkpoint?.version===1){$('restore').disabled=false;$('saved').textContent=`Saved memory found · ${new Date(checkpoint.savedAt).toLocaleString()}`;}}catch{$('saved').textContent='Device storage unavailable. Export a world to keep it.';}requestAnimationFrame(loop);}catch(e){$('error').hidden=false;$('error').textContent=e.message;$('status').textContent='UNAVAILABLE';document.querySelectorAll('button,select,input').forEach(x=>x.disabled=true);}}
$('sim').addEventListener('webglcontextlost',event=>{event.preventDefault();reportFailure('The graphics context was lost. This is a renderer problem, not an experiment outcome.');});
if(document.modelContext?.registerTool){
 const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});
 for(const tool of [{name:'read_echo_world',description:'Read the live ECHO artificial-life metrics and local memory count.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('Expected an empty object');return {tick,running,preset,metrics:lastSample,memories:entries.length,learningUpdates:caretaker.updates};}},{name:'set_echo_paused',description:'Pause or resume the current ECHO simulation.',inputSchema:{type:'object',properties:{paused:{type:'boolean'}},required:['paused'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.paused!=='boolean'||Object.keys(input).some(k=>k!=='paused'))throw new Error('paused must be a boolean');if(!engine?.ok())throw new Error('Simulation unavailable');running=!input.paused;$('play').textContent=running?'Pause':'Resume';draw();return {paused:!running,tick};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}}
}
boot();
